// Builds store/event_results.gs: the catalog builder and the rules engine, exactly as the server runs them,
// followed by the results script. Run after changing api/_lib/catalog.js or api/_lib/events.js:
//   node store/build_event_results.mjs
import fs from "fs";
const strip = (p) => fs.readFileSync(new URL(p, import.meta.url), "utf8").replace(/^import .*$/gm, "").replace(/^export /gm, "");
const out = [
  "// GENERATED by store/build_event_results.mjs. Do not edit here: change api/_lib/*.js or store/event_results.glue.js, then rebuild.",
  "// ── from api/_lib/catalog.js ──", strip("../api/_lib/catalog.js"),
  "// ── from api/_lib/events.js ──", strip("../api/_lib/events.js"),
  strip("./event_results.glue.js"),
].join("\n");
fs.writeFileSync(new URL("./event_results.gs", import.meta.url), out);
console.log("wrote store/event_results.gs", out.length, "chars");
